TLM.f("Sancti/12-28r",{"officium":"Ss. Innocentium","rule":["Gloria","Credo","Prefatio=Nat"],"fallback":"Commune/C3","sections":{"Introitus":[{"k":"ref","la":"Ps 8:3"},{"k":"text","la":"Ex ore infántium, Deus, et lacténtium perfecísti laudem propter inimicos tuos."},{"k":"ref","la":"Ps 8:2"},{"k":"text","la":"Dómine, Dóminus noster: quam admirábile est nomen tuum in univérsa terra!"},{"k":"macro","name":"Gloria"},{"k":"text","la":"Ex ore infántium, Deus, et lacténtium perfecísti laudem propter inimicos tuos."}],"Oratio":[{"k":"text","la":"Deus, cujus hodierna die præcónium Innocéntes Mártyres non loquéndo, sed moriéndo conféssi sunt: ómnia in nobis vitiórum mala mortífica; ut fidem tuam, quam lingua nostra lóquitur, étiam móribus vita fateátur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Apocalýpsis beáti Joánnis Apóstoli"},{"k":"ref","la":"Apoc 14:1-5"},{"k":"text","la":"In diébus illis: Vidi supra montem Sion Agnum stantem, et cum eo centum quadragínta quatuor mília, habéntes nomen ejus, et nomen Patris ejus scriptum in fróntibus suis. Et audívi vocem de cœlo, tamquam vocem aquárum multárum, et tamquam vocem tonítrui magni: et vocem, quam audívi, sicut citharœdórum citharizántium in cítharis suis. Et cantábant quasi cánticum novum ante sedem, et ante quátuor animália, et senióres: et nemo póterat dícere cánticum, nisi illa centum quadragínta quátuor mília, qui empti sunt de terra. Hi sunt, qui cum muliéribus non sunt coinquináti: vírgines enim sunt. Hi sequúntur Agnum, quocúmque íerit. Hi empti sunt ex homínibus primítiæ Deo, et Agno: et in ore eórum non est invéntum mendácium: sine mácula enim sunt ante thronum Dei."}],"Graduale":[{"k":"ref","la":"Ps 123:7-8"},{"k":"text","la":"Anima nostra, sicut passer, erépta est de láqueo venántium."},{"k":"text","la":"Láqueus contrítus est, et nos liberáti sumus: adjutórium nostrum in nómine Dómini, qui fecit cœlum et terram.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 112:1"},{"k":"text","la":"Laudáte, púeri, Dóminum, laudáte nomen Dómini. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 112:1"},{"k":"text","la":"Laudáte, púeri, Dóminum, laudáte nomen Dómini. Allelúja."},{"k":"ref","la":"Eccli 39:19"},{"k":"text","la":"Sancti tui, Dómine, florébunt sicut lílium, et sicut odor bálsami erunt ante te. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 78:3; 78:10"},{"k":"text","la":"Effudérunt sánguinem Sanctórum, velut aquam, in circuitu Jerúsalem,"},{"k":"text","la":"Et non erat, qui sepelíret.","mark":"V"},{"k":"text","la":"V.Víndica, Dómine, sánguinem"},{"k":"text","la":"Sanctórum tuórum, qui effúsus est super terram."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secundum Matthǽum"},{"k":"ref","la":"Matt 2:13-18"},{"k":"text","la":"In illo témpore: Angelus Dómini appáruit in somnis Joseph, dicens: Surge, et áccipe Púerum et Matrem ejus, et fuge in Ægýptum, et esto ibi, usque dum dicam tibi. Futúrum est enim, ut Heródes quærat Púerum ad perdéndum eum. Qui consúrgens accépit Púerum et Matrem ejus nocte, et secéssit in Ægýptum: et erat ibi usque ad óbitum Heródis: ut adimplerétur quod dictum est a Dómino per Prophétam dicéntem: Ex Ægýpto vocávi Fílium meum. Tunc Heródes videns, quóniam illúsus esset a Magis, irátus est valde, et mittens occídit omnes púeros, qui erant in Béthlehem et in ómnibus fínibus ejus, a bimátu et infra, secúndum tempus, quod exquisíerat a Magis. Tunc adimplétum est, quod dictum est per Jeremíam Prophetam dicéntem: Vox in Rama audíta est, plorátus et ululátus multus: Rachel plorans fílios suos, et nóluit consolári, quia non sunt."}],"Offertorium":[{"k":"ref","la":"Ps 123:7"},{"k":"text","la":"Anima nostra, sicut passer, erépta est de láqueo venántium: láqueus contrítus est, et nos liberáti sumus."}],"Secreta":[{"k":"text","la":"Sanctórum tuórum, Dómine, nobis pia non desit orátio: quæ et múnera nostra concíliet, et tuam nobis indulgéntiam semper obtíneat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 2:18"},{"k":"text","la":"Vox in Rama audíta est, plorátus, et ululátus: Rachel plorans fílios suos, et nóluit consolári, quia non sunt."}],"Postcommunio":[{"k":"text","la":"Votíva, Dómine, dona percépimus: quæ Sanctórum nobis précibus, et præséntis, quǽsumus, vitæ páriter et ætérnæ tríbue conférre subsídium."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Oratio":[{"k":"rubric","la":"Pro Octava Nativitatis"},{"k":"text","la":"Concéde, quǽsumus, omnípotens Deus: ut nos Unigéniti tui nova per carnem Natívitas líberet; quos sub peccáti jugo vetústa sérvitus tenet."},{"k":"macro","name":"Per eundem"}],"Commemoratio Secreta":[{"k":"rubric","la":"Pro Octava Nativitatis"},{"k":"text","la":"Obláta, Dómine, múnera, nova Unigéniti tui Nativitáte sanctífica: nosque a peccatórum nostrórum máculis emúnda."},{"k":"macro","name":"Per eundem"}],"Commemoratio Postcommunio":[{"k":"rubric","la":"Pro Octava Nativitatis"},{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut natus hódie Salvátor mundi, sicut divínæ nobis generatiónis est auctor; ita et immortalitátis sit ipse largítor:"},{"k":"macro","name":"Qui tecum"}]},"hr":{"5c6b8910c27eb293":{"t":"Ps 8, 3, Ps 8, 2\n(Ps 8, 3) Iz usta djece i dojenčadi izvodiš, Bože sebi hvalu usprkos svojih neprijatelja. (Ps 8, 2) Gospodine, Gospodine naš, kako li je divno ime tvoje po svoj zemlji!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 8, 3) Iz usta djece i dojenčadi izvodiš, Bože sebi hvalu usprkos svojih neprijatelja."},"04eef584df484741":{"t":"<i>Pomolimo se</i>.\nBože, kojemu na današnji dan nevini mučenici priznaše hvalu ne riječima nego smrću, umrtvi u nama zla svih mana da vjeru u tebe, koju ustima priznajemo, i život naš vladanjem potvrdi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"552eb0c8f0c5a962":{"t":"Otk 14, 1-5\nČitanje knjige Otkrivenja blaženog Ivana Apostola. U one dane: Vidio sam Janje; gdje stoji na gori Sionu i s njim sto četrdeset i četiri tisuće koji su imali na svojim čelima napisano njegovo ime i ime njegova Oca. I čuo sam glas s neba kao buku mnogih voda i kao silnu grmljavinu. A glas koji sam čuo bio je kao glas svirača koji sviraju u svoje citare. I pjevali su novu pjesmu pred prijestoljem i pred četirima životinjama i pred starješinama. I nitko nije mogao pjevati one pjesme, osim onih sto četrdeset i četiri tisuće koji su otkupljeni sa zemlje. Ovo su oni koji se nisu okaljali sa ženama jer su djevci. Ovi idu za Janjetom kamo god pođe. Ovi su otkupljeni između ljudi, prvenci Bogu i Janjetu. Iz njihovih usta nije izašla laž jer su bez mane pred prijestoljem Božjim."},"34b1103cc152df33":{"t":"Ps 123, 7-8\nDuša se naša kao ptica izbavila iz lovačke zamke. Zamka se raskide i mi se izbavismo. Pomoć je naša u imenu Gospodina koji je stvorio nebo i zemlju.\n\nPs 112, 1\n<i>Aleluja</i>, <i>aleluja</i>.\nHvalite, djeco, Gospodina! Hvalite ime Gospodnje! <i>Aleluja</i>."},"737e950d214fc989":{"t":"Mt 2, 13-18\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: Anđeo se Gospodnji javi Josipu u snu i zapovjedi mu; Ustani, uzmi Dijete i njegovu Majku i bježi u Egipat i budi ondje dok ti ne kažem, jer Herod traži da pogubi dijete. On ustade, uze noću dijete i njegovu majku i ode u Egipat. I bio je ondje do Herodove smrti, da se ispuni što je Bog rekao po proroku: Dozvah svoga Sina iz Egipta. Herod videći da su ga mudraci prevarili, silno se rasrdi i naredi da se u Betlehemu i svoj njegovoj okolici po-gube svi dječaci od dvije godine i niže prema vremenu, koje je točno ispitao od mudraca. Tada se ispuni što je rekao prorok Jeremija: Ču se u Rami glas, plač i veliki jauk: Rahela plače za svojim sinovima i ne može se utješiti jer ih nema!"},"420242d00c26cda3":{"t":"Ps 123, 7\nDuša se naša kao ptica izbavila iz lovačke zamke. Zamka se raskide i mi se izbavismo."},"64d0e9711e198e94":{"t":"Ne liši nas, Gospodine, milosne molitve tvojih svetaca, koja neka ti i naše darove učini ugodnima i vazda nam zadobiva tvoje oproštenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"46276ff06c5f858a":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine sveti Oče, svemogući i vječni Bože: jer je po tajni utjelovljene Riječi očima naše duše sinula nova svjetlost tvoga sjaja. Te dok tjelesnim očima spoznajemo Boga, on nas zanosi ljubavlju prema nevidljivim dobrima. I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"23d9badb1e40c0a2":{"t":"Mt 2, 18\nČu se u Rami glas, plač i veliki jauk. Rahela plače za svojim sinovima i ne može se utješiti jer ih nema."},"7ed2a381835aa46f":{"t":"<i>Pomolimo se</i>.\nPošto smo primili, Gospodine, zavjetne darove, daj, molimo, da nam po molitvama svetih pribave pomoć i za sadašnji i za vječni život.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
